//! Shared rendering and atomic materialization for generated agent guidance.

use std::{io, path::Path};

use crate::{distribute::ManagedAssetTarget, settings_local::write_text_atomically};

pub(crate) const MANAGED_BEGIN: &str =
    "<!-- gwt-managed-begin: do not edit; regenerated by gwt -->";
pub(crate) const MANAGED_END: &str = "<!-- gwt-managed-end -->";

pub(crate) struct Guidance<'a> {
    pub name: &'a str,
    pub description: &'a str,
    pub body: &'a str,
    pub claude_section: &'a str,
    pub codex_section: &'a str,
}

impl Guidance<'_> {
    pub fn render(&self, provider: ManagedAssetTarget) -> String {
        let section = match provider {
            ManagedAssetTarget::ClaudeCode => self.claude_section,
            ManagedAssetTarget::Codex => self.codex_section,
            _ => "",
        };
        let extra = if section.is_empty() {
            String::new()
        } else {
            format!("\n{section}")
        };
        format!(
            "---\nname: {name}\ndescription: {description}\n---\n\n{MANAGED_BEGIN}\n\n{body}{extra}\n{MANAGED_END}\n",
            name = self.name,
            description = self.description,
            body = self.body,
        )
    }

    pub fn write(&self, skills_root: &Path, provider: ManagedAssetTarget) -> io::Result<()> {
        write_text_atomically(
            &skills_root.join(self.name).join("SKILL.md"),
            &self.render(provider),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn provider_sections_preserve_common_guidance_and_materialize_idempotently() {
        for guidance in [
            crate::coordination_guidance::GUIDANCE,
            crate::pm_guidance::GUIDANCE,
        ] {
            let original = format!(
                "---\nname: {}\ndescription: {}\n---\n\n{}\n\n{}\n{}\n",
                guidance.name, guidance.description, MANAGED_BEGIN, guidance.body, MANAGED_END,
            );
            let fixture = Guidance {
                claude_section: "## Claude fixture\n\nClaude-specific instructions.\n",
                codex_section: "## Codex fixture\n\nCodex-specific instructions.\n",
                ..guidance
            };
            let dir = tempfile::tempdir().unwrap();
            for (target, root, selected, absent) in [
                (
                    ManagedAssetTarget::ClaudeCode,
                    ".claude",
                    "Claude fixture",
                    "Codex fixture",
                ),
                (
                    ManagedAssetTarget::Codex,
                    ".codex",
                    "Codex fixture",
                    "Claude fixture",
                ),
            ] {
                assert_eq!(
                    guidance.render(target),
                    original,
                    "empty-section compatibility"
                );
                let skills_root = dir.path().join(root).join("skills");
                fixture.write(&skills_root, target).unwrap();
                let path = skills_root.join(guidance.name).join("SKILL.md");
                let first = std::fs::read_to_string(&path).unwrap();
                assert_eq!(first, fixture.render(target));
                assert_eq!(first.matches(guidance.body).count(), 1);
                assert!(first.contains(selected));
                assert!(!first.contains(absent));
                assert!(first.find(selected).unwrap() < first.find(MANAGED_END).unwrap());
                fixture.write(&skills_root, target).unwrap();
                assert_eq!(first, std::fs::read_to_string(&path).unwrap());
            }
            assert_ne!(
                fixture.render(ManagedAssetTarget::ClaudeCode),
                fixture.render(ManagedAssetTarget::Codex)
            );
            assert_eq!(fixture.render(ManagedAssetTarget::Hermes), original);
        }
    }
}
